package org.eclipse.rdf4j.sail.shacl;

import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.StringReader;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.model.vocabulary.RDF4J;
import org.eclipse.rdf4j.repository.RepositoryException;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.Test;

class BulkValuesInjectionTest {

	private static final String EX = "http://example.com/ns#";

	private final ValueFactory valueFactory = SimpleValueFactory.getInstance();
	private final IRI person = valueFactory.createIRI(EX, "person");
	private final IRI newPerson = valueFactory.createIRI(EX, "newPerson");
	private final IRI personClass = valueFactory.createIRI(EX, "Person");
	private final IRI ssn = valueFactory.createIRI(EX, "ssn");
	private final Value firstSsn = valueFactory.createLiteral("first");
	private final Value secondSsn = valueFactory.createLiteral("second");

	private static String shapes(String constraint) {
		return String.join("\n", "",
				"@prefix ex: <http://example.com/ns#> .",
				"@prefix sh: <http://www.w3.org/ns/shacl#> .",
				"",
				"ex:PersonShape",
				"\ta sh:NodeShape ;",
				"\tsh:targetClass ex:Person ;",
				"\tsh:property [",
				"\t\tsh:path ex:ssn ;",
				constraint,
				"\t] .",
				"");
	}

	@Test
	void maxCountViolationSpanningTransactionsIsDetected() throws Throwable {
		SailRepository repository = new SailRepository(new ShaclSail(new MemoryStore()));

		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			connection.add(new StringReader(shapes("\t\tsh:maxCount 1 ;")), "", RDFFormat.TRIG,
					RDF4J.SHACL_SHAPE_GRAPH);
			connection.add(person, RDF.TYPE, personClass);
			connection.add(person, ssn, firstSsn);
			connection.commit();

			connection.begin();
			connection.add(person, ssn, secondSsn);
			assertThrows(ShaclSailValidationException.class, () -> {
				try {
					connection.commit();
				} catch (RepositoryException e) {
					throw e.getCause();
				}
			});
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void minCountViolationForNewTargetIsDetected() throws Throwable {
		SailRepository repository = new SailRepository(new ShaclSail(new MemoryStore()));

		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			connection.add(new StringReader(shapes("\t\tsh:minCount 1 ;")), "", RDFFormat.TRIG,
					RDF4J.SHACL_SHAPE_GRAPH);
			connection.add(person, RDF.TYPE, personClass);
			connection.add(person, ssn, firstSsn);
			connection.commit();

			connection.begin();
			connection.add(newPerson, RDF.TYPE, personClass);
			assertThrows(ShaclSailValidationException.class, () -> {
				try {
					connection.commit();
				} catch (RepositoryException e) {
					throw e.getCause();
				}
			});
		} finally {
			repository.shutDown();
		}
	}
}
